export const MA_APP = "window.__maData={\"logo\": \"https://images.squarespace-cdn.com/content/v1/690a2434f370707dc2fccae4/d91b127e-9c4f-424c-b06b-93eef758943e/MS-ARCHIVES.png?format=1500w\"};\n(function(){\n  var root=document.documentElement,SUB=location.hostname.indexOf('msarchives.')===0;\n  root.classList.add('ms-archives');\n  try{var ld=document.querySelector('#ms-loader .ms-loader__logo img');if(ld&&window.__maData)ld.src=window.__maData.logo}catch(e){}\n  if(SUB)[].forEach.call(document.querySelectorAll('[data-ma]'),function(a){a.setAttribute(a.tagName==='FORM'?'action':'href',a.getAttribute('data-ma'))});\n  function header(){\n    var h=document.querySelector('.ma-hdr');if(!h||h.getAttribute('data-ready'))return;h.setAttribute('data-ready','1');\n    var lb=h.querySelector('.ma-lang__btn'),ll=h.querySelector('.ma-lang__list');\n    lb.addEventListener('click',function(e){e.stopPropagation();var o=ll.hidden;ll.hidden=!o;lb.setAttribute('aria-expanded',o?'true':'false')});\n    document.addEventListener('click',function(){ll.hidden=true;lb.setAttribute('aria-expanded','false')});\n    var bt=h.querySelector('.ma-burger'),mn=document.querySelector('.ma-menu');\n    function menu(o){root.classList.toggle('ma-menu-open',o);bt.setAttribute('aria-expanded',o?'true':'false');mn.setAttribute('aria-hidden',o?'false':'true')}\n    bt.addEventListener('click',function(){menu(!root.classList.contains('ma-menu-open'))});\n    mn.addEventListener('click',function(e){if(e.target.closest('a'))menu(false)});\n    document.addEventListener('keydown',function(e){if(e.key==='Escape'){menu(false);ll.hidden=true}});\n    window.addEventListener('resize',function(){if(window.innerWidth>1024)menu(false)});\n    var ms=h.querySelector('.ma-msearch'),mb=h.querySelector('.ma-hdr__msearch');\n    mb.addEventListener('click',function(){ms.hidden=!ms.hidden;if(!ms.hidden)ms.querySelector('input').focus()});\n    if(document.querySelector('.ma-explore'))ms.hidden=false;\n  }\n  function explore(){\n    var root2=document.querySelector('.ma-explore');if(!root2||root2.getAttribute('data-ready'))return;root2.setAttribute('data-ready','1');\n    var cards=[].slice.call(root2.querySelectorAll('.ma-card')),grid=root2.querySelector('.ma-grid'),tl=root2.querySelector('.ma-timeline'),empty=root2.querySelector('.ma-empty'),count=root2.querySelector('.ma-count');\n    var inputs=[].slice.call(document.querySelectorAll('.ma-hdr input[name=q]'));\n    var q=new URLSearchParams(location.search).get('q')||'';inputs.forEach(function(i){i.value=q});\n    var view='grid',size=window.innerWidth<768?'big':'small';\n    var fp=root2.querySelector('.ma-filter'),fb=root2.querySelector('.ma-tools__filter');\n    function cats(){return [].slice.call(fp.querySelectorAll('input:checked')).map(function(i){return i.value})}\n    function apply(){\n      var s=q.trim().toLowerCase(),c=cats(),shown=[];\n      cards.forEach(function(k){var ok=(!s||k.getAttribute('data-text').indexOf(s)>-1)&&(!c.length||c.indexOf(k.getAttribute('data-cat'))>-1);k.hidden=!ok;if(ok)shown.push(k)});\n      count.textContent=shown.length+(shown.length===1?' entry':' entries');\n      empty.hidden=!!shown.length;\n      grid.classList.toggle('is-small',size==='small');grid.classList.toggle('is-big',size==='big');\n      grid.hidden=view!=='grid'||!shown.length;tl.hidden=view!=='timeline'||!shown.length;\n      if(view==='timeline'){\n        var by={};shown.forEach(function(k){var y=k.getAttribute('data-year');(by[y]=by[y]||[]).push(k)});\n        tl.innerHTML='';\n        Object.keys(by).sort(function(a,b){return b-a}).forEach(function(y){\n          var g=document.createElement('div');g.className='ma-tl';g.innerHTML='<h2 class=\"ma-tl__y\">'+y+'</h2><div class=\"ma-tl__items\"></div>';\n          var it=g.querySelector('.ma-tl__items');by[y].forEach(function(k){var cl=k.cloneNode(true);cl.hidden=false;it.appendChild(cl)});\n          tl.appendChild(g);\n        });\n      }\n      [].forEach.call(root2.querySelectorAll('[data-sw=view] [data-v]'),function(b){b.setAttribute('aria-pressed',b.getAttribute('data-v')===view?'true':'false')});\n      root2.querySelector('[data-sw=view]').classList.toggle('is-end',view==='timeline');\n      [].forEach.call(root2.querySelectorAll('[data-sw=size] [data-v],.ma-msize [data-v]'),function(b){b.setAttribute('aria-pressed',b.getAttribute('data-v')===size?'true':'false')});\n      root2.querySelector('[data-sw=size]').classList.toggle('is-end',size==='small');\n      fb.classList.toggle('is-active',c.length>0);\n    }\n    function sw(name,fn){var w=root2.querySelector('[data-sw='+name+']');\n      w.querySelectorAll('[data-v]').forEach(function(b){b.addEventListener('click',function(){fn(b.getAttribute('data-v'));apply()})});\n      w.querySelector('.ma-switch__track').addEventListener('click',function(){var bs=w.querySelectorAll('[data-v]');fn(w.classList.contains('is-end')?bs[0].getAttribute('data-v'):bs[1].getAttribute('data-v'));apply()})}\n    sw('view',function(v){view=v});sw('size',function(v){size=v});\n    root2.querySelectorAll('.ma-msize [data-v]').forEach(function(b){b.addEventListener('click',function(){size=b.getAttribute('data-v');apply()})});\n    function openF(o){fp.hidden=!o;fb.setAttribute('aria-expanded',o?'true':'false');root.classList.toggle('ma-filter-open',o)}\n    fb.addEventListener('click',function(){openF(fp.hidden)});\n    root2.querySelector('.ma-filter__close').addEventListener('click',function(){openF(false)});\n    fp.addEventListener('change',apply);\n    root2.querySelector('.ma-filter__reset').addEventListener('click',function(){fp.querySelectorAll('input').forEach(function(i){i.checked=false});apply()});\n    document.querySelectorAll('.ma-hdr form').forEach(function(f){f.addEventListener('submit',function(e){e.preventDefault();q=f.querySelector('input').value;inputs.forEach(function(i){i.value=q});var u=new URLSearchParams();if(q)u.set('q',q);history.replaceState(null,'',location.pathname+(q?'?'+u:''));apply()})});\n    inputs.forEach(function(i){i.addEventListener('input',function(){q=i.value;inputs.forEach(function(j){if(j!==i)j.value=q});apply()})});\n    apply();\n  }\n  header();explore();\n})();\n"
